CREATE OR REPLACE FUNCTION public.audit_changes() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ DECLARE actor uuid; BEGIN actor := auth.uid(); IF TG_TABLE_NAME = 'packages' AND TG_OP = 'UPDATE' THEN IF OLD.price IS DISTINCT FROM NEW.price THEN INSERT INTO public.package_price_history(package_id, old_price, new_price, reason, changed_by) VALUES (NEW.id, OLD.price, NEW.price, COALESCE(NULLIF(current_setting('app.price_reason', true), ''), 'Perubahan harga'), actor); END IF; END IF; IF TG_OP = 'INSERT' THEN INSERT INTO public.activity_logs(user_id, action, entity_type, entity_id, description) VALUES (actor, 'buat', TG_TABLE_NAME, NEW.id, 'Data dibuat'); ELSE INSERT INTO public.activity_logs(user_id, action, entity_type, entity_id, description) VALUES (actor, 'ubah', TG_TABLE_NAME, NEW.id, 'Data diubah'); END IF; RETURN NEW; END $$;